NIGHT_LOADED({"seed":1017,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,2,3,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":6,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0002,"rank":0.0882,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000602","role":"target","render":{"description":"Man ziet huis in brand staan, en voelt dat de muren warm zijn, een voorteken dat het huis zal afbranden.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42965","original":"2 Voorloop.\nOp een morgen ging ik naar het werk. \nDaar zag ik opeens het huis van Timp in brand staan.\nNu moet men daar zo snel mogelijk heen gaan.\nZijn de muren koud, dan komt er een dode in dat huis, zijn de muren warm, dan brandt het op.\nIk voelde dus, de muren waren warm.\nDadelijk ging ik naor de vrouw terug.\nIk zeg: \"Timp zien hoes brandt gauw op.\"\nHet heeft nog twee jaar geduurd, toen ging het.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.3651,"rank":0.7227,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KEUNING005704","role":"intruder","render":{"description":"Spook dat vrouw zou zijn die na haar dood is teruggekomen, blijkt echtgenote te zijn die buiten op haar man wacht.","place":"Ureterp","prov":"Fr.","year":1962,"code":"SINSAG 0450","initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131193","original":"Sa waerd der ek forteld, dat by de Hegebrêgge jouns let in frommis, dat koartlyn forstoarn wie, om spûke. Mar hwat blykte it to wêzen? In man, dy ticht by de brêge wenne, wie der jouns faek op út. As hy dan let thúskaem, waerd syn wiif ûngerêst. Dan roun dy dêr by de brêge hinne en wer. Hja woe it net wite, dat sy dat wie en dêrom sloech hja altyd de skelk om de holle.","lang":"Fries","front":"original"},"home":"cab:4"},{"id":"c2","story_id":"CJ083803","role":"member","render":{"description":"Iemand voorspelt dat een familielid zes weken later zal sterven. De voorspelling klopt precies.","place":"Eastermar","prov":"Fr.","year":1969,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32807","original":"Yn 'e famylje fan myn wiif to Burgumerheide wie ien tige min. De famylje kom delsetten. (Mar hy is wer better woarn).\nDoe sei ien fan 'e famyljeleden: \"Mei seis wiken binne wy wer byinoar.\"\nOp 'e kop om't ôf, krekt seis wiken letter stoar der in broer fan skoanheit. Dat wie Sjouke Dykstra.\nDyselde hie 't dus wol goed sjoen.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"CJ049804","role":"member","render":{"description":"Een vrouw voorspelt dat een doodzieke man niet zal sterven. Iedereen verklaart haar voor gek, maar de vrouw krijgt gelijk: de man leeft nog.","place":"Kootstertille","prov":"Fr.","year":1968,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24848","original":"Myn buorman Bauke Brinkman wie tige min. Hy hie kanker en sy seinen allegear, hy soe stjerre. Hy lei yn 't sikenhûs. Mar ik sei: \"Bauke giet net dea en hy komt wer.\"\nDe lju seinen: \"Dat kin net. Hy is sà min.\"\nMar ik sei: \"Hy bliuwt yn libben.\" Hwant ik hie mear sjoen. Hy libbet nòch. 't Is nou al jierren lyn.\nSyn soan wennet nou op 'e buorkerij.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c4","story_id":"CJ082319","role":"member","render":{"description":"Een waarzegster doet toekomstvoorspellingen. De voorspellingen komen allemaal uit.","place":"Kootstertille","prov":"Fr.","year":1970,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32678","original":"Thomas Clare wenne yn 'e Westerein oan 'e Swâdde.\nMyn beide susters ha dêr ris hinne west, hwant Clare koe wiersizze. Fan myn iene suster sei se, dy soe trouwe mei in swarte man en sy soe oan 't wetter komme to wenjen. 't Is neikom: har man wie roetswart en sy kommen yn Gerkeskleaster to wenjen oan 'e feart.\nDer wie ek noch in nichtsje by. Dy har âlden koenen och sa min mei elkoar, dat wie in great lijen, dat ús nichtsje sei altyd: \"Ik wol noait trouwe.\"\nClare sei tsjin har: \"Jo sille èk trouwe.\"\n\"Ik trou nèt\", sei ús nichtsje.\n\"Ja hear,\" sei Clare, \"jo sille trouwe mei in widner mei bern.\"\nEn 't is èk gebeurd. Clare hie 't wol goed sjoen.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Ureterp hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c2","c3","c4"]}},{"id":"1-3","type":"R1","difficulty":1.0771,"rank":0.0042,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ031107","role":"omen","render":{"description":"Als er een spiegel naar beneden valt, sterft er binnen zes weken iemand.","place":"Twijzelerheide","prov":"Fr.","year":1967,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21986","original":"As in spegel delkomt, komt der binnen seis wiken in sippe deaden.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CBAK0041","role":"omen","render":{"description":"Voorspelling dat een kind niet oud zal worden. Het kind sterft inderdaad op zes-jarige leeftijd.","place":"Broek in Waterland","prov":"N.-H.","year":1899,"code":"SINSAG 0489","initials":"C.B.","url":"https://www.verhalenbank.nl/items/show/8638","original":"Grietje Holleman heeft tegen een broertje van een Broeker dame gezegd dat hij niet oud zou worden. Op zes-jarige leeftijd is hij overleden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"},{"id":"c3","story_id":"WEV013104","role":"omen","render":{"description":"Lijk dat zondag overstaat betekent binnen zes weken weer een sterfgeval .","place":"Bellingwolde","prov":"Gr.","year":1966,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44380","original":"n Volksgeleuf was wieder, dat as ain liek n zundag overstun, dat er den binnen zes weekn weer ['n] staarfgeval komen zol.","lang":"Gronings","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","6 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":6},"on_success":{"chime":6,"digit":{"value":6,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P4","difficulty":1.7084,"rank":0.7471,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"LAAN004b","role":"top","render":{"description":"Tilbusscher laat in een van zijn aardigste artikelen in 't Nieuwsblad van 't Noorden een oud vrouwtje aan het woord: Witte Wijven waren niet lelijk en","place":"Lellens","prov":"Gr.","year":1930,"code":"SINSAG 0310","initials":"E.F.","url":"https://www.verhalenbank.nl/items/show/41806","half":"top"},"home":"2-1"},{"id":"c2","story_id":"ZEEUW053","role":"distractor","render":{"description":"De geest neemt hem mee door gangen, deuren en zalen, tot ze komen bij 5 kisten, waarop een grote zwarte hond zit, die hem de adem in de keel doet stokken. Hij is niet meer in staat te spreken en de geest neemt voor 100 jaar afscheid en de man staat weer op de weg, waar hij werd aangesproken, en sleept zich huiswaarts en is 2 dagen later dood. Iemand hoorde van zijn avontuur, ging het ook wagen, zag om middernacht een licht voor zich uit dansen, kreeg de schrik en vluchtte weg.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c3","story_id":"KEMP314","role":"distractor","render":{"description":"Het was lelijk met hem afgelopen als het een andere dag was geweest. De juffrouw geeft hem de mogelijkheid om haar geldkisten op te graven: die hij kan verdelen tussen hemzelf, de armen en de kerk. De volgende dinsdag gaat Drikus met zijn zwager Hannes de schat opgraven. Maar als Hannes zegt: 'kijk, daar zit de heks', zinken de kisten dieper dan ooit.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c4","story_id":"LYST030","role":"distractor","render":{"description":"Als tegenprestatie moet ze naakt door de kerk rennen. Ze doet dit met tegenzin. Later is er op de grond die ze heeft gekregen, een wit wief te zien. Men is ervan overtuigt dat de geest van de vrouw daar nog rondspookt.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c5","story_id":"YPFOE088","role":"distractor","render":{"description":"Hij is dat op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c6","story_id":"LYST283","role":"distractor","render":{"description":"En inderdaad, een wit wief vertoont zich aan hem. De dominee zegt tegen de gedaante dat het mag blijven als het door God gestuurt is, maar dat het moet weggaan als het door de duivel gezonden is. De verschijning verdwijnt onmiddellijk.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c7","story_id":"ZEEUW056","role":"distractor","render":{"description":"De man ziet dat de hond de duivel is, laat zich weer naar boven brengen, waarna hij wordt vervloekt. Hij komt ziek thuis, en blijft lang ziek. Zijn hele leven blijft hij arm.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c8","story_id":"KEUNING001109","role":"distractor","render":{"description":"met gevlochten manen staat, merkt dat om middernacht paard lawaai maakt en ziet bij het maken van licht een vrouw op het paard.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c9","story_id":"CJ103307","role":"distractor","render":{"description":"Omdat hij dacht haar te kennen, wilde hij haar groeten, maar toen hij dichterbij kwam ging ze in rook op.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c10","story_id":"CBOEK305","role":"distractor","render":{"description":"Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c11","story_id":"TINNEV065","role":"distractor","render":{"description":"Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c12","story_id":"CJ001413","role":"distractor","render":{"description":"Hij heeft zijn tante vermoord om haar geld en sinds die tijd spookt het er. Dit alles gebeurt dichtbij de plek waar het huis van sterke Hearke heeft gestaan.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c13","story_id":"LAAN004b","role":"bottom","render":{"description":"spierwit gekleed. Zij waren gek op kerels. In Waarvem kwamen ze vaak bij elkaar. Ze dansten om een dikke boom. Ze zwaaiden met witte doeken met bloedvlekken erop. In Slochter gingen ze naast mensen lopen. Ze deden er niemand kwaad. Op de Wedder Brug dansten en zongen zij.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0310. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c13"},"on_success":{"fuse":["c1","c13"],"stack":["c1","c13"]},"found_card":{"card":"c13"}},{"id":"2-2","type":"P3","difficulty":1.2302,"rank":0.7455,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ029903","role":"intruder","render":{"description":"Een bruidspaar is op weg naar het gemeentehuis, als de aanstaande bruidegom zijn bruid ineens een stuk uit het schort bijt. De man is een weerwolf; het meisje maakt het terstond uit.","place":"Kûkherne","prov":"Fr.","year":1953,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21918","original":"It gebeurde us dat twa jonge lju yn 'e wein sieten nei 't gemeentehûs ta. Hja soenen dy deis trouwe. Underweis yn 'e wein byt de man har in stik út 'e skelk. Hy wie in wjerwolf. Hja makke it fuort út.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:3"},{"id":"c2","story_id":"CBOEK477","role":"member","render":{"description":"Een knecht moet in een weddenschap aantonen, dat hij de spit in de Witte Wieven-kuil durft te gooien. Hij gooit en daagt het witte wief uit, dat hem achtervolgt. Met paard en al springt de knecht over de onderdeur. Het witte wief gooit de spit, dat in de middelaar van de deur blijft zitten.","place":"Bathmen","prov":"Ov.","year":1892,"code":null,"initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/39631","original":"In de buurtschap Loo, op het erve Noever ging men een weddenschap aan met een knecht, dat hij het spit niet durfde gooien in de Witte-wieven-kuul; deze bevond zich daar ergens in de buurt. Hij sprong te paard en joeg derwaarts, aldaar smeet hij het spit in de kuil met de woorden:\n\nWit wieven wit\nHier breng ik oe een spit\n(of: Wat heb ie'j op oe spit?)\n\nDaarop had het wit wief gezegd:\n\nA'j zoo lang wacht\nDak mien eene schoe toeknuppe\nEn de aander toerukke\nDan zal ie'j 't gebraad wezen.\n\nDe knecht rende toen in vliegenden vaart huiswaarts, achtervolgd door het wit wief en voor de achterdeur gekomen, was de bovendeur los en de onderdeur dicht, maar het paard was nogal vlug en sprong over de onderdeur. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"LYST279","role":"member","render":{"description":"Een boerenknecht brengt het spit naar de Witte Wieve. Een van hen achtervolgt hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel. Het Witte Wief kon niet sneller lopen, omdat ze problemen had met een van haar schoenen.","place":"Tilligte","prov":"Ov.","year":1937,"code":null,"initials":"B.R.","url":"https://www.verhalenbank.nl/items/show/13623","original":"Door ouden wordt nog van de Wit Wieve verteld, die alleen kwaadaardig waren, wanneer ze getergd werden. Zo wordt verteld dat een boerenknecht eens het spit bracht naar de plaats, waar zij woonden. Hij werd door eene der witte wieve achtervolgd, doch hem niet kon inhalen, omdat ze in de haast maar een schoen had kunnen aantrekken. Toen de knecht het huis binnenvluchtte, wierp ze hem met een bijl achterna, die in de steil (deurpost) terecht kwam.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"ENGELB_15_003","role":"member","render":{"description":"Over bestaan van witte wieven en spit in deurpost.","place":"Geesteren","prov":"Ov.","year":1979,"code":null,"initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128566","original":"H.E.: Van de witn wiew he’j doar wa mangs van heurd?\nVr.Vr.: Van de witn wiew is ok niks van woar.\nH.E.: Nee, mer te geet ok um t verhaal, he. Joa he’j hier nog zonnen beuld, zonnen witn wievnbeuld. Ne, nee, nee (door elkaar heen gepraat, ze zijn het met elkaar niet eens)\nVr. [Wolberink, Jan]: Wat hadn ze bie ouns ok zegd, oh jee no valt mie t kenneke in zee Dat stun nog moal vuur joarn in de Twentse kraant. Als ik t met ene schoen had vastgebondn, gevondn als de ander gebondn.\nA.Ve.: ... t spit nog in n stiel van n nienduur nog zitn.\nF.Ve.: t Spit brengn.","lang":"Twents","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Kûkherne hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":3},"on_success":{"trail_note":2,"unlock_cabinet":3,"stack":["c2","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0661,"rank":0.6949,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"LYST277","role":"card","render":{"description":"Een boerenknecht komt langs de Witte Wieve en daagt ze uit. Een van hen achtervolgt hem tot huis. Hij kan net naar binnen vluchten. Ze gooit echter een knuppel naar de deur, waardoor er een stuk van de stiepel breekt.","place":"Almelo","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"A.G.K.","url":"https://www.verhalenbank.nl/items/show/13621","original":"In Almelo gaat onder oudere personen (70 - 80 jaar) het verhaal rond van de Witte Wieve van de Alberger hei. Zij vertellen het volgende:\nAlbergen is een gehucht op zes kilometer afstand van Almelo aan de weg naar Ootmarsum. De Alberger hei strekte zich vroeger uit tussen dit gehucht en de bezittingen van Huize Almelo. Men dacht dat ze woonden in een grote tumulus, die zich in 't midden bevond. Men zegt dan, dat als voorzorgsmaatregel, dat de witte wieve niet in huis zouden komen, de boerenbehuizingen een kruis in de middenpost van de baanderdeur, \"stiepel\" genaamd, hadden aangebracht op ongeveer een meter. …","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-3"},{"id":"c2","story_id":"TINNEV317","role":"sill","render":{"description":"Fietser ziet 's avonds zijn weg geblokkeerd door twee dames in het wit met paarden en moet terug (later werd hij ziek).","place":"Zevenaar","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22664","stain":"twee"},"home":"2-3"},{"id":"c3","story_id":"HOL002604","role":"card","render":{"description":"Witte juffer die de weg vraagt, gooit hoed vol geld, en verdwijnt.","place":"Tiel","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210163","original":"Berend, den dakuil (een Van Uden) smeerde de daken van binnen aan met kalk, vandaar dat hij deze bijnaam kreeg. Eens liep Berend op de Grotebrugse grintweg bij de Twaalf Apostelen (straatje) toen een witte juffer hem de weg vroeg naar het veer. Berend zei haar die en nadat hij dit gedaan had, gooide zij hem de hoed vol met \"Berliner daolder\". Driemaal was Berend dit overkomen. Bij het veer gekomen wilde Berend haar bedanken, maar hij kreeg geen kans daartoe: zij was verdwenen.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c4","story_id":"CJ111721","role":"card","render":{"description":"Op een spookplaats spookt een vrouw in het wit. De spookvrouw is alleen 's nachts te zien. De paarden zijn erg bang voor de spookvrouw.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29932","original":"Yn 'e Westerein spûke in frommes, dat sweefde yn wite klean by de wâllen lâns. Hja hie in bân om 'e rôkken hinne. Men seach har allinne by nacht.\nAs de kooplju yn 'e nacht út 'e Westerein wei mei de hynders nei de merk ta gongen, dan koenen se de hynders net fierder krije as dy wite juffer der wer spûke. Dy hynders wienen dan bang.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c5","story_id":"BOEKV095","role":"card","render":{"description":"Een meisje, dat rogge sneed, werd door Ellert gekidnapt en moet dagelijks zijn vader Brannert scheren; ze snijdt hem de nek af, etc. De nageworpen bijl komt in de deurdrempel, wat nog te zien is.","place":"Amen","prov":"Dr.","year":1881,"code":"SINSAG 0161","initials":"G.J.B.","url":"https://www.verhalenbank.nl/items/show/34976","original":"In eene andere Drentsche lezing heeten de roovers Ellert en Brannert en wordt gezegd dat hun hol te vinden was tusschen Zweeloo en Schoonoord. Het meisje had groene rogge gesneden op den esch (1) toen Ellert haar gevangen nam. Hij dwingt haar zijn vader dagelijks te scheren en zij maakt nu tijdens zijne afwezigheid gebruik van het scheermes om dezen te dooden. Overigens is het verhaal hetzelfde. De bijl vliegt in den drempel van de huisdeur, waar dit nog zichtbaar is. \n\n1. bouwland.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ007910","role":"card","render":{"description":"Bij Hattum de Vries in het laantje spookte 's nachts altijd een wit wijf. De mensen durfden er 's nachts niet te komen, want ze werden er door dat witte wijf aan de kant gedreven naar het meertje toe. Zonder dat ze zelf iets deden, kwamen ze in het meertje terecht.","place":"Oudega","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17053","original":"By Hattum de Vries yn it loantsje spoeke nachts altyd in wyt wiif. De minsken doarsten dêr nachts noait to kommen. Hwant sy waerden dêr stadich troch dat wite wiif oan kant treaun nei de dobbe ta. Sûnder dat se it sels fornamen kommen se yn 'e dobbe torjochte.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een Z.","Zevenaar. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c2","object":"window","text":"Zevenaar"},"on_success":{"digit":{"value":2,"card":"c2","word":"twee","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P5","difficulty":0.679,"rank":0.375,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"LYST274","role":"variant","render":{"description":"Knecht, die 's nachts in een wolf verandert, verdwijnt als de boer onder zijn bed een wolfshuid vindt en verbrandt.","place":"Drogteropslagen","prov":"Dr.","year":1937,"code":"SINSAG 0824","initials":"K.J.","url":"https://www.verhalenbank.nl/items/show/13538","original":"Vroeger was hier een knecht, die 's nachts in een wolf veranderde en het de mensen dan lastig maakte. Onder zijn bed vond de boer op zekere dag een wolfshuid en verbrandde die. Sedert was de knecht verdwenen.\n(Verteld door een zeventig-jarige).","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c2","story_id":"VVUNL301","role":"variant","render":{"description":"Een knecht wordt weerwolf door een leren riem, die hij verstopt. Deze wordt gevonden en in de oven verbrand; meteen komt de verdachte knecht te paard aansnellen, maar wordt tegengehoudcen en zegt als de riem verbrand is: \"Ik ben verlost!\"","place":"Echt","prov":"L.","year":1920,"code":"SINSAG 0824","initials":"F.S.S.","url":"https://www.verhalenbank.nl/items/show/35840","original":"De weerwolf \n\nOp de hoeve Bosscherhof woonde eertijds een knecht die een lederen riem bezat, welke de macht had, hem, indien hij hem omgordde, te betoveren als weerwolf. Geheimzinnig en zorgvuldig werd deze band telkenmale door de knecht verstopt en wat men ook deed, hoe men ook spiedde, men vond hem nooit. En geregeld hadden de mensen uit de omtrek, die laat huiswaarts keerden, de weerwolf te dragen. En ook iedereen herkende steeds de knecht. Men gaf elkander raad om wanneer men overvallen werd, de weerwolf op een of andere manier te prikken of te krab-ben tot hij bloed voelde of zag. Dan was men gered. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c3","story_id":"LINSSEN002605","role":"variant","render":{"description":"Knecht die om middernacht door velg in zwarte kat verandert, is verlost na verbranden van velg.","place":"Baexem","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208342","original":"Volgens tweede verteller was er op Nelishof te Tungelroy een knecht die elke nacht tussen twaalf en een uur afwezig was. Door een raampje ging hij naar buiten. Hij klom dan op de schansenhoop en kwam er als kat af. De boer had hem bespied en gemerkt dat boven op de schansenhoop een velg lag van een karwiel. Die had de boer daar niet neergelegd en hij zocht verband tussen de spokerij (zwarte kat) en dat karwiel.\nDit zou hij vernietigen als de knecht afwezig was. Op zekere dag had hij hem met schapen naar Antwerpen gestuurd. Toen hij een dag weg was stak de boer zijn bakoven aan en wierp de velg erin.\nOp hetzelfde moment verscheen de knecht en wilde de oven in. Het gelukte slechts met drie man om hem daarvan te weerhouden. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Limburg werd een dier gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"3-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1920.","Op die kaart staat een dier. Welk?"],"lock":{"kind":"word","salt":"20ba0dd8dad087ce","accepted_hashes":["49e355a9f15be6a7563be14249a911b21d2b180ace27532f7d2c919bb0e99797","4ef948617dd74f3ba15fd97637d5bcf012913827551dec21d46cf3dfdb1407b5","5b10a04e1d2bcf3bf2d7cca65414b67fa643e25fc88a496e9e9e77b3c6fe8ccc","7cfed2230794ab2af97a37f23709e16b667cc4a7c25238ae3dfe0dd5b12f08cb","a357c0a404d0958fc4cf8ca6aa1ad25f85fa38c0e1e892f9cb5064badb120391","b1a4b70d4dd10ad7bad015c0c03c15f986b7b40fdee89dfc76f9ca728a690ea5"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.2475,"rank":0.7798,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015102","role":"intruder","render":{"description":"Een ongeduldige, ruwe boer wil voor de avond een groot stuk land omgeploegd hebben. De knecht vertikt het en zegt de boer dat hij maar naar de duivel kan lopen met zijn voorstel. De boer vat dit letterlijk op en schakelt de hulp van de duivel in. De volgende morgen is het land omgeploegd. Zijn dwepen met de duivel is de boer duur komen te staan: op zijn sterfbed werd hij door de duivel opgehaald.","place":"Hurdegaryp","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19770","original":"Der wie in boer, dat wie in forwoesteling. Hy wie altyd gleonhastich en net in arbeider dy't it by him úthâlde koe. Op in kear hied er wer in arbeider, doe moest der ploege wurde. It wie al let yn 'e joun en it wie ûnmooglik dy greate hoeke lân foar de nacht noch to ploeijen. Dat de arbeider sei tsjin 'e boer: \"Freegje de duvel, dat dy it docht.\" De boer sei: \"Dat dog ik\" en hy die it ek.\nDe oare moarns wie it stik lân ploege.\nMar hy hat it sûr bikeapje matten. Doe't er op syn stjerbêd lei, hat de duvel him helle.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c2","story_id":"VVUNL049","role":"member","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":null,"initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"ENGELS000115","role":"member","render":{"description":"Weerwolf bespringt 's avonds mensen; als helper bij werk; verandering in weerwolf door aantrekken verborgen jas, na verbranden jas bevrijding.","place":"Helden","prov":"L.","year":1962,"code":null,"initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/57969","original":"Weerwolven:\nMannen, die wat laat op de baan waren, werden, vooral in donkere, stormachtige nachten soms besprongen door de weerwolf. Dit spookdier met gloeiende ogen sprong hen op de rug, en klemde zich met de voorpoten om hun nek. Ze bleven zich als een zware last aan de verschrikte man klemmen totdat hij ergens een huis bereikte. In de Broekbeemd, tussen Onder-Eijndt en Zandberg, stond ergens een holle eiken knot of poesjt. Er was een man, die als weerwolf bekend werd. Hij had een aparte jas; als hij deze aantrok werd hij weerwolf. Na zijn nachtelijke tochten verborg hij deze jas in die holle “poesjt”. Zijn buurlui ontdekten dit, en staken de “poesjt” met de jas in brand. …","lang":"Standaardnederlands; Limburgs","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"KEMP298","role":"member","render":{"description":"Een pachter komt erachter dat een kleine scheper op zijn boerderij vermoedelijk een weerwolf is. Hij stuurt hem weg voor een dag en hij en zijn knechten ontdekken in een holle wilg een wolvenvel. Ze steken het thuis in brand. De scheper keert vervolgens in razend tempo terug en wil zijn vel teruggrijpen. Als dat niet lukt, vlucht de scheper naar de holle boom en is nooit meer teruggezien.","place":"Broek","prov":"L.","year":1925,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43423","original":"Het weerwolfsvel verbrand\n\nBij de pachter van de boerderij bij het kasteel Geusselt onder Amby diende eens een scheper, een klein manneke, dat de naam had een weerwolf te zijn. 's Nachts was hij nooit in bed te vinden, maar 's morgens lag hij er weer in. De knechts van de hoeve hadden dat al dikwijls bemerkt.\nWijl dit zo opvallend was, werd zijn doen en laten gedurig bespied en zo bemerkte men dan ook dat hij, wanneer hij 's avonds uit zijn bed kroop, naar een weide ging, waar heel eenzaam een grote holle wilg stond. Daar verdween hij iedere keer in.\nOm het fijne van de zaak te achterhalen stuurde de pachter hem op zekere namiddag naar een dorp, dat meer dan drie uur van de hoeve lag, om daar koeien te kopen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Hurdegaryp hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c2","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.079,"rank":0.6923,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"TINNEV043","role":"card","render":{"description":"Twee mannen zijn grasstengels aan het snijden, als de ene man aan de andere vraagt of hij hem eens wil zien. Meteen daarop ligt er een wolf in het gras. De man wil nooit meer met de ander werken.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0804","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22389","original":"30.\nOp een andere kier vroeg Dorus aan Peter, toe ze aan 't smele sui'je ware: \"Wi'j um is zien?\" Medeen derop lei een grote wolf ien 't gres. Peter wol van toe af aan de niet meer met Dorus op uut.","lang":"Liemers","front":"description"},"home":"3-3"},{"id":"c3","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"CJ039818","role":"door","render":{"description":"Een van zeven op elkaar volgende zonen is een weerwolf.","place":"Harkema","prov":"Fr.","year":1968,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23535"},"home":"3-3"},{"id":"c5","story_id":"LYST189","role":"card","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c4","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c2","c3","c5"]}}]},{"id":4,"label":"Spoken","digit":3,"drawers":[{"id":"4-1","type":"P6","difficulty":3.2243,"rank":0.4419,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CJ043716","role":"clip1","render":{"description":"Twee mannen liepen eens in de manenschijn, toen ze de verschijning van een mens voor zich zagen. Even later was de verschijning weer verdwenen.","place":"Ikkerwâld","prov":"Fr.","year":1968,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24022","original":"Der wienen twa mannen, dy kommen fan Feanwâlden. 't Wie ljochtmoannewaar. Doe wie der in ding fóár har. 't Hie de forskining sahwat fan in minske. Dat wie hyltyd in eintsje fóár har. Doe stapten se fan 'e fyts. Doe woarde 't wei yn 'e wâl. Sy ha 't net wer sjoen.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ007512","role":"clip2","render":{"description":"Op een pad spookt het. De verteller heeft er eens drie vrouwen en een man gezien. Er rolt 's nachts een rol vijfschacht [weefsel van linnen en wol], maar men kan het nooit te pakken krijgen.","place":"Kollumersweach","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17001","original":"Op itselde paed oan 'e Swadde, dêr't ik yndertiid yn 'e nacht de trije froulju en dy keardel troffen ha, spûket nachts in rolle fyfskaft om. Men koe it noait krije. It lei stil, mar as men der op taroun, om it to pakken, rolle it fuort. Men krige noait in kâns.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ020904","role":"clip3","render":{"description":"Een man zag zijn vader om twaalf uur 's nachts een gerst naar de koe brengen. Maar in werkelijkheid lag zijn vader gewoon in bed.","place":"Harkema","prov":"Fr.","year":1967,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20692","original":"Fokke Weening fortelde ek, hy kom us op in nacht om tolve ûre thús. Doe seach er syn heit mei in earmfol gers, dat er nei de koe brochte. (Se hienen mar ien koe) Hy seach it tige dúdlik, mar yn werklikheit wie 't sa net. Hwant syn heit lei op dat stuit op bêd to sliepen.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":"CJ028211","role":"inside","render":{"description":"Op een spookplaats is iedere dag een witte gedaante te zien. Als je de spookverschijning nadert, is hij even plotseling als hij verschenen is weer verdwenen.","place":"Houten","prov":"Utr.","year":1967,"code":"SINSAG 0478","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21708","original":"Op de Heilige Berg tussen een dikke boom en de beek zagen ze telkens een witte gedaante. Elke dag was die er te zien. Maar 't gekke was, als je der dicht bij kwam, dan was die gedaante opeens verdwenen.","lang":"Standaardnederlands","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 2.","2 — 3 — 12."],"lock":{"kind":"number3","salt":"20ba0dd8dad087ce","accepted_hashes":["f46d13d677f0c63e422db47b9c6142a45541f241a81c812210b98047d5a9de6c"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.1592,"rank":0.6209,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"VRIES006005","role":"member","render":{"description":"Gevallen van toverij en spokerij, afkopen van betovering door betaling aan dokter die kan toveren, zwarte kat in bedstee.","place":"Axel","prov":"Zl.","year":1971,"code":null,"initials":"J.d.V.","url":"https://www.verhalenbank.nl/items/show/209468","original":"ZWARTE KUNST RONDOM ZAAMSLAG.\n\nDaar liep vroeger een padje van 't Turp naar de Groenstrate. \nDaar in de buurte ei moeder vroeger geweund. A moeder in 't schemerdonker langs dà padje liep, stond d 'er wel is een klein sliepsteentje mee een bakje water d 'er onder. En da dieng stong zomaa te draaien, zonder datter iemand ankwam.\nZe zei dà thuus en der broers zeien: \"daa moe je nie meer langs lopen (h)oor!\"\n't Gebeurden ook wè, dat ze swinters de waste (was) op zolder te drogen iengen (hingen) en dan was 't daa boven soms een leven as een oordeel. Toen à ze giengen kiekken zagen ze de kousen gewoon rechtop over de zolder lopen. …","lang":"Zeeuws","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"VRIES002602","role":"member","render":{"description":"Plaaggeest in de vorm van lange man spookt op boerderij.","place":"Zaamslag","prov":"Zl.","year":1963,"code":null,"initials":"J.d.V.","url":"https://www.verhalenbank.nl/items/show/209242","original":"IN DE SCHUUR VAN SCHELFHOUT. \n\n\"'t Verhaal over \"den ouwen Roose\" ken U misschien nog niet, meneer? \nDat is veel langer geleden, want mijn moeder had het al als kind van haar moeder gehoord.\nRoose, die op deVal woonde, stond in de hele buurt bekend als een vent die je nergens bang mee kon krijgen en dat wou in die dagen rondom de Val wet wat zeggen! Zeker ook, omdat er in de buurt al een paar vreemde dingen gebeurd waren.\nOp een zomernacht gaat Roose, 1e knecht bij boer Schelfhout, die in de Grote Huijssenspolder woonde, een kwartiertje lopen van deVal af, om 2 uur op weg. 't Is oogsttijd en al vroeg moeten de paarden aan 't werk kunnen gaan. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"CJ037017","role":"intruder","render":{"description":"Op een spookplaats zijn witte wieven gesignaleerd.","place":"Garyp","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22990","original":"Oan 'e Akkereed by de Brandsma-wei yn Garyp spoeken wite wiven, seinen se.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c4","story_id":"VRIES002906","role":"member","render":{"description":"Vrouw wordt in de schemering bij de keel gegrepen.","place":"Zaamslag","prov":"Zl.","year":1963,"code":null,"initials":"J.d.V.","url":"https://www.verhalenbank.nl/items/show/209256","original":"'k bin zelf nooit bange gewist, ma kort bie de kreke an Pauwvliet (aan hoofdweg Axel-Zaamslag) bin 'k is bie m 'en kele gegrepen; 't was tussen licht en donker.\nWad of 't gewist is weet ik nie. De politie ei-ter nog na gezocht, ma z 'en niks kunnen vinden.\n\nNoe, meer weet ik nie meer. Misschien datter me later nog wè wat invalt, dad oor je dan nog wè; in bedankt da je gewist ziet!","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Garyp hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c1","c2","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1123,"rank":0.25,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ081906","role":"top","render":{"description":"Een turfschipper die steeds opgeschrikt wordt door een naakt kindje achter het schip raadpleegt de dominee. De dominee vraagt het kind - dat allang overleden is - waarom het geen rust kan vinden.","place":"Dokkum","prov":"Fr.","year":1970,"code":"SINSAG 0402","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32618","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CBAK0016","role":"half","render":{"description":"Na de dood van de vrouw wordt het huis afgebroken. Vanwege de bewering dat het er spookte omdat er onrechtvaardig geld verborgen is wordt naar een schat gezocht.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c3","story_id":"CJ081906","role":"bottom","render":{"description":"Het kind blijkt op die plaats verdronken en vervolgens zonder doodskleed begraven te zijn. Het kind verzoekt de dominee de middelste van drie vrouwen om een doodshemd te vragen. De wens wordt vervuld en de dominee reikt het kind het doodskleed aan met een houten lepel. Nu de wens van het kind vervuld is vindt het rust.","half":"bottom","code":"SINSAG 0402","stain":"drie"},"home":"4-3"},{"id":"c4","story_id":"CJ041201","role":"half","render":{"description":"De eerste nachten na de begrafenis werd de man wakker omdat er op de ruiten getikt werd. Hij hoorde dan zijn dode vrouw vragen om haar gouden been. De derde nacht heeft hij het been buiten voor de deur gezet. De volgende ochtend was het verdwenen, en zijn vrouw is nooit meer bij hem komen spoken.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c5","story_id":"CJ061713","role":"half","render":{"description":"Daarna verdwijnt hij.Bearn is bang geweest. Het mannetje is pikzwart en snuift de hele tijd.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c6","story_id":"CJ065118","role":"half","render":{"description":"Want als men er niet aan kan voldoen, dan krijgt de dode nooit rust in zijn graf en gaat hij spoken.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"WEV015701","role":"half","render":{"description":"Boer vertelt dat vrouw die er is vermoord zo nu en dan spookt.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘dominee’ opnieuw.","Het nummer is SINSAG 0402. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c3","object":"typewriter"},"on_success":{"fuse":["c1","c3"],"type_line":"Verteller: de vorige assistent.","digit":{"value":3,"card":"c1","word":"drie","stained":"c3"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
